export const questions={numbers:[{q:'What is the value of the digit 7 in the number 3 742 581?',opts:['700 000','70 000','7 000 000','7 000'],ans:0},{q:'Round 4 836 295 to the nearest 100 000.',opts:['4 800 000','4 900 000','4 836 000','5 000 000'],ans:0},{q:'Which number is 100 more than 2 999 900?',opts:['3 000 000','2 999 000','3 000 900','2 999 990'],ans:0},{q:'What is the LCM of 4 and 6?',opts:['12','24','6','8'],ans:0},{q:'What is the HCF of 18 and 24?',opts:['6','3','12','9'],ans:0},{q:'Which is a prime number?',opts:['37','51','49','77'],ans:0},{q:'What is 3⁴ (3 to the power of 4)?',opts:['81','64','27','12'],ans:0},{q:'A school has 12 600 learners. 4 200 are in Grade 6. What fraction is Grade 6?',opts:['1/3','1/4','2/5','1/2'],ans:0},{q:'What is the square root of 144?',opts:['12','14','11','13'],ans:0},{q:'Write 3 204 781 in words.',opts:['Three million two hundred and four thousand seven hundred and eighty-one','Three hundred and two million four thousand seven hundred and eighty-one','Thirty-two million four hundred and seven hundred and eighty-one','Three billion two hundred and four thousand'],ans:0}],fractions:[{q:'What is ¾ + ⅝?',opts:['11/8 (1⅜)','8/12','5/12','1½'],ans:0},{q:'What is ⅔ × ¾?',opts:['½','6/12','8/12','3/8'],ans:0},{q:'Write 0.45 as a fraction in simplest form.',opts:['9/20','45/10','4/5','9/10'],ans:0},{q:'What is 15% of 200?',opts:['30','25','35','15'],ans:0},{q:'Which fraction is greater: 5/8 or 3/5?',opts:['5/8','3/5','They are equal','Cannot tell'],ans:0},{q:'If ⅓ of a number is 24, what is the number?',opts:['72','8','48','36'],ans:0},{q:'What is 2½ - ¾?',opts:['1¾','1½','2¼','1¼'],ans:0},{q:'A pizza is cut into 8 slices. Thabo ate 3 slices. What fraction is left?',opts:['5/8','3/8','4/8','2/8'],ans:0}],geometry:[{q:'How many lines of symmetry does a regular hexagon have?',opts:['6','3','4','8'],ans:0},{q:'What type of angle is 125°?',opts:['Obtuse','Acute','Right','Reflex'],ans:0},{q:'A quadrilateral with one pair of parallel sides is called a…',opts:['Trapezium','Parallelogram','Rhombus','Rectangle'],ans:0},{q:'What is the sum of interior angles of a triangle?',opts:['180°','360°','90°','270°'],ans:0},{q:'A triangular prism has how many faces?',opts:['5','6','4','7'],ans:0},{q:'What is the name of a polygon with 8 sides?',opts:['Octagon','Hexagon','Heptagon','Decagon'],ans:0},{q:'What is 360° ÷ 6? (Interior angle of a regular hexagon)',opts:['60°','72°','90°','45°'],ans:0},{q:'A cube has how many edges?',opts:['12','8','6','16'],ans:0}],measure:[{q:'How many millilitres are in 3.5 litres?',opts:['3 500 mℓ','350 mℓ','35 000 mℓ','3 050 mℓ'],ans:0},{q:'A race is 5 km. Convert to metres.',opts:['5 000 m','500 m','50 000 m','5 00 m'],ans:0},{q:'A bag of oranges weighs 2.75 kg. What is that in grams?',opts:['2 750 g','275 g','27 500 g','2 075 g'],ans:0},{q:'It is 09:45. What time will it be in 2 hours 30 minutes?',opts:['12:15','11:45','12:45','11:15'],ans:0},{q:'What is the temperature difference between 38°C and -4°C?',opts:['42°C','34°C','42°F','36°C'],ans:0},{q:'A rectangle is 8 cm long and 5 cm wide. What is its perimeter?',opts:['26 cm','40 cm','13 cm','20 cm'],ans:0},{q:'How many centimetres in 3.2 metres?',opts:['320 cm','32 cm','3 200 cm','3.2 cm'],ans:0},{q:'A film starts at 14:25 and lasts 1 hour 45 minutes. When does it end?',opts:['16:10','15:70','15:10','16:25'],ans:0}],data:[{q:'Data set: 3, 7, 2, 7, 5, 8, 7. What is the mode?',opts:['7','5','3','8'],ans:0},{q:'Data set: 4, 6, 8, 10, 12. What is the median?',opts:['8','6','10','7'],ans:0},{q:'Data set: 10, 20, 30, 40. What is the mean?',opts:['25','20','30','100'],ans:0},{q:'Data set: 5, 12, 3, 19, 7. What is the range?',opts:['16','14','19','12'],ans:0},{q:'A pie chart shows 25% for soccer. If 200 learners were surveyed, how many prefer soccer?',opts:['50','25','75','100'],ans:0},{q:'Which type of graph is best for showing change over time?',opts:['Line graph','Bar graph','Pie chart','Pictograph'],ans:0},{q:'Data: 14, 9, 22, 14, 7. What is the mean? (Round to nearest whole number)',opts:['13','14','11','15'],ans:0},{q:'Which average is most affected by a very large outlier?',opts:['Mean','Median','Mode','Range'],ans:0}]};export const factorSets={12:[1,2,3,4,6,12],18:[1,2,3,6,9,18],24:[1,2,3,4,6,8,12,24],30:[1,2,3,5,6,10,15,30],36:[1,2,3,4,6,9,12,18,36]};export const pctProblems=[{q:'What is 20% of 350?',ans:70,unit:''},{q:'Write 3/4 as a percentage.',ans:75,unit:'%'},{q:'A shirt costs R240 with a 15% discount. What is the discount amount?',ans:36,unit:'R'},{q:'What is 35% of 600?',ans:210,unit:''},{q:'Write 0.6 as a percentage.',ans:60,unit:'%'},{q:'A soccer team won 18 of 24 games. What percentage did they win?',ans:75,unit:'%'},{q:'What is 5% of 1 200?',ans:60,unit:'R'},{q:'A book costs R80. VAT is 15%. What is the VAT amount?',ans:12,unit:'R'}];export const areaProblems=[{type:'Rectangle',l:8,w:5,unit:'cm'},{type:'Rectangle',l:12,w:7,unit:'m'},{type:'Rectangle',l:15,w:9,unit:'cm'},{type:'Square',l:6,w:6,unit:'m'},{type:'Square',l:11,w:11,unit:'cm'},{type:'Rectangle',l:20,w:4,unit:'m'}];
